import sys

from durations import parse_duration, format_duration


def main():
    total = 0
    for line in sys.stdin:
        text = line.strip()
        if not text:
            continue
        try:
            total += parse_duration(text)
        except ValueError:
            print(f"invalid duration: {text}", file=sys.stderr)
            return 1
    print(format_duration(total))
    return 0


if __name__ == "__main__":
    sys.exit(main())
